import {DirtSurface} from './tactile.js?v=4';
import {EXTRA_JOBS} from './catalog.js?v=4';
import {RepairTask} from './repair-tasks.js';
export const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
export const JOBS=[
 {id:'fan',name:'停转的小风扇',owner:'邻居阿姨',note:'“它陪我过了好多夏天，再帮它转起来吧。”',number:'01',palette:[0x25bdb6,0xf2ad50,0xa896e5],dirt:[[-.65,1.9,.31],[.6,2.25,.31],[.15,2.62,.31],[-.5,1.15,.31],[.52,1.1,.31],[-.45,.22,.62],[.45,.22,.62]],parts:[{id:'rotor',slot:'rotor',name:'四叶扇叶',symbol:'✣',color:'#efb54b',position:[0,1.85,.34]}],bolts:[[-.62,1.17,.36],[.62,1.17,.36]],finish:'风又回来啦。',test:'按住测试，看小风扇重新转起来'},
 {id:'radio',name:'没声音的收音机',owner:'唱歌的爷爷',note:'“早上没有它的声音，总觉得少了点什么。”',number:'02',palette:[0xf6b64e,0x66c6b8,0xef9684],dirt:[[-.92,1.45,.52],[-.45,1.26,.61],[.13,1.48,.52],[.85,1.4,.52],[-.82,.55,.52],[.15,.45,.52],[.9,.55,.52]],parts:[{id:'antenna',slot:'antenna',name:'伸缩天线',symbol:'↟',color:'#6c9cbf',position:[-1.05,1.85,.02]},{id:'dial',slot:'dial',name:'调频旋钮',symbol:'◉',color:'#8d83c2',position:[.75,.95,.63]}],bolts:[],finish:'熟悉的歌，回来了。',test:'按住试听，听见一段清楚的旋律'},
 {id:'robot',name:'困困的小机器人',owner:'隔壁的小朋友',note:'“它说好今天陪我玩，可是怎么叫都不醒。”',number:'03',palette:[0xa38cde,0x59c4b6,0xf1a459],dirt:[[-.35,2.05,.45],[.3,1.85,.45],[-.72,1.4,.32],[-.3,1.1,.5],[.35,1.1,.5],[.55,.75,.5],[-.4,.3,.32],[.4,.3,.32]],parts:[{id:'cell-a',slot:'cell-a',name:'青色能量块 +',symbol:'+',color:'#46bfae',position:[-.35,1.03,.53]},{id:'cell-b',slot:'cell-b',name:'橙色能量块 −',symbol:'−',color:'#efa76a',position:[.35,1.03,.53]}],bolts:[[0,.64,.55]],finish:'你好呀，小伙伴。',test:'按住唤醒，它会向你挥挥手'}
,...EXTRA_JOBS].map(spec=>{
 const policy={fan:['brush','装回扇叶'],radio:['none','接回天线和旋钮'],robot:['none','更换能量块'],lamp:['none','换上灯泡'],car:['none','装回车轮'],bike:['none','贴住漏气点'],clock:['none','装回齿轮'],guitar:['none','装上弦组'],bear:['none','盖好爱心布片'],can:['wash','换上洒水喷头']}[spec.id];
 return {...spec,cleaning:policy[0],assembleLabel:policy[1],cleanLabel:spec.id==='fan'?'软刷除尘':'清洗壶身',repairFirst:spec.id==='lamp',dirt:policy[0]==='none'?[]:spec.dirt};
});
export const PHASE_LABELS={clean:'擦掉灰尘',assemble:'装回零件',screw:'拧紧螺丝',tune:'找到好声音',repair:'专属维修',test:'修复测试',done:'修好啦'};
export function collectCards(jobs,existing=[]){return [...new Set([...existing,...jobs.filter(j=>j.returned).map(j=>j.spec.id)])].filter(id=>JOBS.some(s=>s.id===id));}
export class RepairJob{
 constructor(spec,saved={}){this.spec=spec;this.cleaned=new Set((saved.cleaned||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<spec.dirt.length));this.surfaces=spec.dirt.map((_,i)=>new DirtSurface(i+spec.number*9,saved.surfaces?.[i]));for(const i of this.cleaned)this.surfaces[i].finish();this.installed=new Set((saved.installed||[]).filter(id=>spec.parts.some(p=>p.id===id)));this.bolts=spec.bolts.map((_,i)=>clamp(Number(saved.bolts?.[i])||0));this.boltsPlaced=spec.bolts.map((_,i)=>this.bolts[i]>0||!!saved.boltsPlaced?.[i]);this.tuneValue=clamp(Number.isFinite(saved.tuneValue)?saved.tuneValue:.14);this.tuneStable=0;this.calibrated=spec.id==='radio'?!!saved.calibrated:true;this.time=Math.max(0,Number(saved.time)||0);this.started=!!saved.started;this.testProgress=0;this.events=[];this.repairs=(spec.steps||[]).map((def,i)=>new RepairTask(def,saved.repairs?.[i]));this.returned=!!saved.returned;this.completed=!!saved.completed&&this.cleaned.size===spec.dirt.length&&this.installed.size===spec.parts.length&&this.bolts.every(v=>v>=1)&&this.calibrated&&this.repairs.every(t=>t.done);if(this.completed)this.testProgress=1;this.finishResidue();}
 get phase(){if(this.cleaned.size<this.spec.dirt.length)return 'clean';if(this.spec.repairFirst&&this.repairs?.some(t=>!t.done))return 'repair';if(this.installed.size<this.spec.parts.length)return 'assemble';if(this.spec.id==='radio'&&!this.calibrated)return 'tune';if(this.bolts.some(v=>v<1))return 'screw';if(this.repairs?.some(t=>!t.done))return 'repair';return this.completed?'done':'test';}
 get activeTask(){return this.repairs?.find(t=>!t.done);}
 action(kind,data){if(this.phase!=='repair')return {changed:false};this.started=true;const task=this.activeTask,result=task.act(kind,data);if(result.done){this.event('repairStep',{name:task.def.name});this.changed('repair');}if(result.wrong)this.event('repairWrong',{repairType:task.type});return result;}
 returnItem(){if(!this.completed||this.returned)return false;this.returned=true;return true;}
 event(type,data={}){this.events.push({...data,type});}
 changed(before){if(before!==this.phase)this.event('phase',{phase:this.phase});}
 clean(i){if(this.phase!=='clean'||!Number.isInteger(i)||this.cleaned.has(i)||i<0||i>=this.spec.dirt.length)return false;const before=this.phase;this.started=true;this.cleaned.add(i);this.event('clean',{index:i});this.changed(before);return true;}
 brush(i,u,v,radius,amount,tool){if(this.phase!=='clean'||this.cleaned.has(i)||!this.surfaces[i]||(this.spec.cleaning==='brush'?tool!=='brush':!['spray','wipe'].includes(tool)))return false;this.started=true;const surface=this.surfaces[i],changed=surface.apply(u,v,radius,amount,tool==='brush'?'dust':tool);if(surface.progress>.91){surface.finish();this.clean(i);}this.finishResidue();return changed>0;}
 finishResidue(){if(this.phase==='clean'&&this.cleaningProgress>=.94){for(let i=0;i<this.surfaces.length;i++)if(!this.cleaned.has(i)){this.surfaces[i].finish();this.clean(i);}}}
 get cleaningProgress(){return this.surfaces.length?this.surfaces.reduce((n,s,i)=>n+(this.cleaned.has(i)?1:s.progress),0)/this.surfaces.length:1;}
 install(id,slot){if(this.phase!=='assemble'||this.installed.has(id))return false;this.started=true;const p=this.spec.parts.find(p=>p.id===id);if(!p||p.slot!==slot){this.event('wrong');return false;}const before=this.phase;this.installed.add(id);this.event('install',{id});this.changed(before);return true;}
 placeBolt(i){if(this.phase!=='screw'||!Number.isInteger(i)||i<0||i>=this.bolts.length||this.boltsPlaced[i])return false;this.boltsPlaced[i]=true;this.started=true;this.event('placeBolt',{index:i});return true;}
 tighten(i,amount){if(this.phase!=='screw'||!this.boltsPlaced[i]||!Number.isFinite(amount)||i<0||i>=this.bolts.length||this.bolts[i]>=1)return false;const before=this.phase;this.started=true;this.bolts[i]=clamp(this.bolts[i]+amount);if(this.bolts[i]>=1)this.event('bolt',{index:i});this.changed(before);return true;}
 tune(value){if(this.phase!=='tune')return;this.started=true;this.tuneValue=clamp(value);}
 get tuned(){return this.tuneValue>=.62&&this.tuneValue<=.76;}
 update(dt,testing=false){if(this.completed)return;if(this.started)this.time+=dt;const before=this.phase;if(before==='repair'){const task=this.activeTask;if(task.update(dt)){this.event('repairStep',{name:task.def.name});this.changed('repair');}}if(before==='tune'){this.tuneStable=this.tuned?this.tuneStable+dt:0;if(this.tuneStable>=.6){this.calibrated=true;this.event('calibrated');this.changed(before);}}if(this.phase==='test'){if(testing)this.started=true;this.testProgress=clamp(this.testProgress+(testing?dt/1.4:-dt*.45));if(this.testProgress>=1){this.completed=true;this.event('complete');this.changed('test');}}}
 toJSON(){return {returned:this.returned,repairs:this.repairs.map(t=>t.toJSON()),cleaned:[...this.cleaned],surfaces:this.surfaces.map(s=>s.toJSON()),installed:[...this.installed],bolts:this.bolts,boltsPlaced:this.boltsPlaced,tuneValue:this.tuneValue,calibrated:this.calibrated,time:this.time,started:this.started,completed:this.completed};}
}
